"use client";

import { useState, useMemo } from "react";
import { ChevronLeft, ChevronRight, Plus, X, Clock } from "lucide-react";
import { format, addMonths, subMonths, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameMonth, isSameDay, addDays } from "date-fns";
import { nl } from "date-fns/locale"; 
import { createCalendarItem } from "@/app/actions/task-actions";
import { useRouter } from "next/navigation";

export default function CalendarClient({ initialTasks = [] }: { initialTasks: any[] }) {
  const router = useRouter();
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  
  // Form State
  const [loading, setLoading] = useState(false);
  const [title, setTitle] = useState("");
  const [time, setTime] = useState("12:00"); // Varsayılan saat
  const [type, setType] = useState("agenda");

  const taskMap = useMemo(() => {
    const map: any = {};
    initialTasks.forEach((item) => {
      if (item.startDatetime) {
        const d = new Date(item.startDatetime);
        const dateKey = format(d, "yyyy-MM-dd");
        if (!map[dateKey]) map[dateKey] = [];
        map[dateKey].push(item);
      }
    });
    // Saatlere göre sıralayalım ki takvimde düzgün dursun
    Object.keys(map).forEach(key => {
      map[key].sort((a: any, b: any) => 
        new Date(a.startDatetime).getTime() - new Date(b.startDatetime).getTime()
      );
    });
    return map;
  }, [initialTasks]);

  const handleSave = async () => {
    if (!title || !selectedDate) return;
    setLoading(true);

    const payload = {
      titel: title,
      documentType: type,
      datum: format(selectedDate, "yyyy-MM-dd"),
      uure: time, // "14:30" gibi gidiyor
    };

    try {
      const res = await createCalendarItem(payload);
      if (res.success) {
        setTitle("");
        setTime("12:00");
        setSelectedDate(null);
        router.refresh();
        setTimeout(() => window.location.reload(), 300);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-[1600px] mx-auto px-4 py-8">
      {/* ... Header Kısmı Aynı ... */}

      <div className="bg-[#0a0e17] border border-white/10 rounded-3xl overflow-hidden shadow-2xl">
        <div className="grid grid-cols-7 bg-white/5 py-4 border-b border-white/10 text-center text-[10px] font-black text-teal-500/40 uppercase tracking-widest">
          {["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"].map(d => <span key={d}>{d}</span>)}
        </div>
        <div className="grid grid-cols-7">
          {(() => {
            const days = [];
            let day = startOfWeek(startOfMonth(currentMonth), { weekStartsOn: 1 });
            const endDate = endOfWeek(endOfMonth(currentMonth), { weekStartsOn: 1 });

            while (day <= endDate) {
              const dateKey = format(day, "yyyy-MM-dd");
              const dayTasks = taskMap[dateKey] || [];
              const isCurrentMonth = isSameMonth(day, currentMonth);

              days.push(
                <div 
                  key={day.toString()} 
                  onClick={() => setSelectedDate(day)}
                  className={`min-h-[160px] border border-white/5 p-3 hover:bg-white/[0.02] cursor-pointer relative ${!isCurrentMonth ? "opacity-10" : "opacity-100"}`}
                >
                  <span className="text-xs text-teal-500/30 mb-2 block">{format(day, "d")}</span>
                  <div className="space-y-1">
                    {dayTasks.map((t: any) => (
                      <div key={t.id} className="text-[10px] px-2 py-1 bg-white/5 border border-white/10 rounded text-white flex justify-between items-center">
                        <span className="truncate flex-1">{t.title}</span>
                        <span className="text-[8px] text-fuchsia-500 font-mono ml-1">
                          {format(new Date(t.startDatetime), "HH:mm")}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              );
              day = addDays(day, 1);
            }
            return days;
          })()}
        </div>
      </div>

      {/* MODAL / FORM */}
      {selectedDate && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-md p-4">
          <div className="bg-[#0E153A] border border-white/10 p-8 rounded-[32px] w-full max-w-md shadow-2xl">
            <h3 className="text-fuchsia-500 font-black text-[10px] tracking-widest uppercase mb-6">Nieuwe Afspraak</h3>
            
            <div className="space-y-6">
              {/* Başlık Girişi */}
              <input 
                value={title} onChange={(e) => setTitle(e.target.value)} 
                className="w-full bg-[#070B24] border border-white/10 p-4 text-white rounded-xl outline-none focus:border-fuchsia-500" 
                placeholder="Wat is de planning?" 
              />

              {/* Saat Seçici (Yeni Eklendi) */}
              <div className="flex items-center gap-4 bg-[#070B24] border border-white/10 p-4 rounded-xl">
                <Clock className="text-teal-500" size={20} />
                <input 
                  type="time" 
                  value={time} 
                  onChange={(e) => setTime(e.target.value)}
                  className="bg-transparent text-white outline-none w-full font-mono text-xl"
                />
              </div>

              {/* Kategori ve Kaydet Butonu ... (Öncekiyle Aynı) */}
              <button 
                onClick={handleSave} 
                className="w-full bg-white text-black font-black py-4 rounded-xl hover:bg-fuchsia-500 hover:text-white transition-all uppercase"
              >
                {loading ? "Bezig..." : "Bevestigen"}
              </button>
              <button onClick={() => setSelectedDate(null)} className="w-full text-white/30 uppercase text-[10px] tracking-widest">Annuleren</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}